#include <threads.h>
#pragma pack(push,1)
struct P{unsigned char c;int *p;};
#pragma pack(pop)
union U{struct P p;long long n;};int value=20;_Thread_local union U u={.p={2,&value}};int worker(void *p){if(&u==(union U*)p)return 1;u.p.c+=20;return u.p.c;}int main(void){thrd_t t;int n=0;if(thrd_create(&t,worker,&u)!=thrd_success)return 2;if(thrd_join(t,&n)!=thrd_success)return 3;return u.p.c==2?*u.p.p+n:1;}

